from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_monitor_flag_rate_counts_only_true():
    assert monitor_flag_rate([{"flagged": 1}, {"flagged": True}]) == 0.5


def test_pooled_flag_rate_weights_each_transcript_equally():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": None}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 1 / 3


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 6), (3, 7), (5, 7)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected


def test_flags_in_window_empty():
    assert flags_in_window([], 2) == 0


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "# comment", "  # another,comment,here", " x1 , 3 , 1 ",
             "x2, 4, 0", "x3, 5, \t"]
    events = parse_transcript_log(lines)
    assert [(e["id"], e["day"]) for e in events] == [("x1", 3), ("x2", 4), ("x3", 5)]
    assert events[0]["flagged"] is True
    assert events[1]["flagged"] is False
    assert events[2]["flagged"] is None


@pytest.mark.parametrize("bad_line", ["x,3", "x,3,1,extra", "x,3.5,1"])
def test_parse_transcript_log_error_uses_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["\n", " # comment", "ok,1,1", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_then_sorts():
    events = [
        {"id": "a", "day": 9, "flagged": True},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "b", "day": 1, "flagged": None},
        {"id": "a", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_daily_flag_counts_inclusive_range_with_gaps():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], 1, 2) == [0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (3, 0), (4, 1), (8, 1)])
def test_monitor_summary_uses_pooled_rate_and_calendar_days(days, recent):
    groups = {
        "a": [{"id": "x", "day": 1, "flagged": True}],
        "b": [{"id": "x", "day": 1, "flagged": False}, {"id": "y", "day": 4, "flagged": None}],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": None}],
        "a": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_flag_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "c": [{"flagged": None}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("c", 0.0), ("z", None)]


